// HBM: `_cache_metas` is derived from `_cache_brewsLocal`, but upstream only ever
		// invalidates it in `_setBrewMetas`. Any sync source lookup (`hasSourceJson`,
		// `sourceJsonToAbv`, ...) that runs before this async load lands therefore freezes
		// the table with only the localStorage-backed metas in it — every brew loaded from
		// `homebrew/` then renders as its raw source id, and loses its source colour, for
		// the rest of the page's life. Drop the derived caches now the real inputs are in.
		this._cache_metas = null;
		this._cache_sourceStyles = null;
		return this._cache_brewsLocal = brewDocs;
